#!/usr/bin/env python3
"""Validate an evidence-backed review adjudication record."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
from collections import Counter
from pathlib import Path
from typing import Any


SHA256_RE = re.compile(r"^[0-9a-f]{64}$")
STATUSES = {"CONFIRMED", "PARTIAL", "REFUTED", "UNRESOLVED"}
FIX_ASSESSMENTS = {"safe", "unsafe", "owner_decision", "not_provided", "needs_design"}
VERDICTS = {"READY_FOR_IMPLEMENTATION", "NO_CONFIRMED_DEFECTS", "BLOCKED"}


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def nonempty(value: Any) -> bool:
    return value is not None and value != "" and value != [] and value != {}


def require_keys(obj: Any, keys: set[str], where: str, errors: list[str]) -> None:
    if not isinstance(obj, dict):
        errors.append(f"{where} must be an object")
        return
    for key in sorted(keys - set(obj)):
        errors.append(f"missing {where}.{key}")


def valid_sha(value: Any) -> bool:
    return isinstance(value, str) and bool(SHA256_RE.fullmatch(value))


def validate(data: Any, artifact: Path | None, contract_file: Path | None) -> list[str]:
    errors: list[str] = []
    require_keys(data, {"schema_version", "adjudication_id", "source", "contract", "review_sources", "findings", "summary", "adjudication"}, "root", errors)
    if not isinstance(data, dict):
        return errors
    if data.get("schema_version") != "1.0":
        errors.append("schema_version must be 1.0")
    if not nonempty(data.get("adjudication_id")):
        errors.append("adjudication_id must be non-empty")

    source = data.get("source", {})
    require_keys(source, {"reviewed_artifact", "sha256", "artifact_intact"}, "source", errors)
    source_hash = source.get("sha256") if isinstance(source, dict) else None
    if not valid_sha(source_hash):
        errors.append("source.sha256 must be 64 lowercase hex characters")
    if artifact is not None:
        if not artifact.is_file():
            errors.append(f"artifact does not exist: {artifact}")
        elif valid_sha(source_hash) and sha256_file(artifact) != source_hash:
            errors.append("artifact hash does not match source.sha256")

    contract = data.get("contract", {})
    require_keys(contract, {"required", "path", "sha256", "contract_id", "artifact_sha256", "status", "stale"}, "contract", errors)
    contract_blocked = False
    if isinstance(contract, dict):
        required = contract.get("required")
        if not isinstance(required, bool):
            errors.append("contract.required must be boolean")
        if not isinstance(contract.get("stale"), bool):
            errors.append("contract.stale must be boolean")
        if required:
            if not nonempty(contract.get("path")) or not nonempty(contract.get("contract_id")):
                errors.append("required contract needs path and contract_id")
            if not valid_sha(contract.get("sha256")):
                errors.append("required contract.sha256 is invalid")
            if contract.get("status") != "PASS":
                errors.append("required contract must have PASS status")
            if not valid_sha(contract.get("artifact_sha256")):
                errors.append("required contract.artifact_sha256 is invalid")
            elif valid_sha(source_hash) and contract.get("artifact_sha256") != source_hash:
                errors.append("contract artifact hash does not match source hash")
            contract_blocked = contract.get("stale") is True or contract.get("status") != "PASS"
            if contract_file is None:
                errors.append("required contract needs --contract-file verification")
            elif not contract_file.is_file():
                errors.append(f"contract file does not exist: {contract_file}")
            else:
                if valid_sha(contract.get("sha256")) and sha256_file(contract_file) != contract.get("sha256"):
                    errors.append("contract file hash does not match contract.sha256")
                try:
                    actual_contract = json.loads(contract_file.read_text(encoding="utf-8"))
                except (OSError, json.JSONDecodeError) as exc:
                    errors.append(f"cannot parse contract file: {exc}")
                else:
                    if actual_contract.get("contract_id") != contract.get("contract_id"):
                        errors.append("contract_id does not match the verified contract file")
                    if actual_contract.get("source", {}).get("sha256") != contract.get("artifact_sha256"):
                        errors.append("contract artifact_sha256 does not match the verified contract file")
                    if actual_contract.get("gate", {}).get("status") != contract.get("status"):
                        errors.append("contract status does not match the verified contract file")
        else:
            for key in ("path", "sha256", "contract_id", "artifact_sha256", "status"):
                if contract.get(key) is not None:
                    errors.append(f"optional contract.{key} must be null")

    reviews = data.get("review_sources")
    if not isinstance(reviews, list) or not reviews:
        errors.append("review_sources must be a non-empty list")
    else:
        for index, review in enumerate(reviews):
            require_keys(review, {"review_id", "path", "sha256"}, f"review_sources[{index}]", errors)
            if isinstance(review, dict) and not valid_sha(review.get("sha256")):
                errors.append(f"review_sources[{index}].sha256 is invalid")

    findings = data.get("findings")
    counts: Counter[str] = Counter()
    held_count = 0
    if not isinstance(findings, list):
        errors.append("findings must be a list")
        findings = []
    seen_ids: set[str] = set()
    required_finding = {"finding_id", "source_review", "quoted_finding", "type", "severity", "scientific_dimension", "held_decision", "status", "source_locations", "defect_evidence", "refuting_evidence", "mechanical_checks", "reasoning", "proposed_fix_assessment", "disposition"}
    for index, finding in enumerate(findings):
        require_keys(finding, required_finding, f"findings[{index}]", errors)
        if not isinstance(finding, dict):
            continue
        finding_id = finding.get("finding_id")
        if not nonempty(finding_id):
            errors.append(f"findings[{index}].finding_id must be non-empty")
        elif finding_id in seen_ids:
            errors.append(f"duplicate finding_id: {finding_id}")
        seen_ids.add(finding_id)
        status = finding.get("status")
        if status not in STATUSES:
            errors.append(f"findings[{index}].status is invalid")
        else:
            counts[status] += 1
        if not isinstance(finding.get("held_decision"), bool):
            errors.append(f"findings[{index}].held_decision must be boolean")
        elif finding.get("held_decision"):
            held_count += 1
        if not isinstance(finding.get("source_locations"), list) or not finding.get("source_locations"):
            errors.append(f"findings[{index}].source_locations must be non-empty")
        for key in ("defect_evidence", "refuting_evidence", "mechanical_checks"):
            if not isinstance(finding.get(key), list):
                errors.append(f"findings[{index}].{key} must be a list")
        if not nonempty(finding.get("reasoning")):
            errors.append(f"findings[{index}].reasoning must be non-empty")
        if finding.get("proposed_fix_assessment") not in FIX_ASSESSMENTS:
            errors.append(f"findings[{index}].proposed_fix_assessment is invalid")
        if status == "CONFIRMED" and not finding.get("defect_evidence"):
            errors.append(f"findings[{index}] CONFIRMED requires defect_evidence")
        if status == "REFUTED" and not finding.get("refuting_evidence"):
            errors.append(f"findings[{index}] REFUTED requires refuting_evidence")
        if status == "PARTIAL" and (not finding.get("defect_evidence") or not finding.get("refuting_evidence")):
            errors.append(f"findings[{index}] PARTIAL requires defect_evidence and refuting_evidence")

    summary = data.get("summary", {})
    require_keys(summary, {"total", "confirmed", "partial", "refuted", "unresolved", "held_decisions"}, "summary", errors)
    if isinstance(summary, dict):
        expected = {
            "total": len(findings),
            "confirmed": counts["CONFIRMED"],
            "partial": counts["PARTIAL"],
            "refuted": counts["REFUTED"],
            "unresolved": counts["UNRESOLVED"],
            "held_decisions": held_count,
        }
        for key, value in expected.items():
            if summary.get(key) != value:
                errors.append(f"summary.{key} must equal {value}")

    adjudication = data.get("adjudication", {})
    require_keys(adjudication, {"verdict", "checked_at", "reasons"}, "adjudication", errors)
    if isinstance(adjudication, dict):
        verdict = adjudication.get("verdict")
        if verdict not in VERDICTS:
            errors.append("adjudication.verdict is invalid")
        if not isinstance(adjudication.get("reasons"), list) or not adjudication.get("reasons"):
            errors.append("adjudication.reasons must be a non-empty list")
        has_defects = counts["CONFIRMED"] + counts["PARTIAL"] > 0
        has_unresolved = counts["UNRESOLVED"] > 0
        artifact_intact = source.get("artifact_intact") is True if isinstance(source, dict) else False
        if verdict == "READY_FOR_IMPLEMENTATION" and (not has_defects or has_unresolved or contract_blocked or not artifact_intact):
            errors.append("READY_FOR_IMPLEMENTATION requires defects, intact/current inputs, and no unresolved findings")
        if verdict == "NO_CONFIRMED_DEFECTS" and (has_defects or has_unresolved or contract_blocked or not artifact_intact):
            errors.append("NO_CONFIRMED_DEFECTS requires no defects, no unresolved findings, and intact/current inputs")
        if (contract_blocked or not artifact_intact or has_unresolved) and verdict != "BLOCKED":
            errors.append("stale/broken inputs or unresolved findings require BLOCKED")
    return errors


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("record", type=Path)
    parser.add_argument("--artifact", type=Path, required=True)
    parser.add_argument("--contract-file", type=Path)
    args = parser.parse_args()
    try:
        data = json.loads(args.record.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        print(f"INVALID: {exc}", file=sys.stderr)
        return 1
    errors = validate(data, args.artifact, args.contract_file)
    if errors:
        for error in errors:
            print(f"INVALID: {error}", file=sys.stderr)
        return 1
    print(f"VALID: {args.record}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

